// Hand-written `koa-router` stub for the flowatlas fixture suite.
//
// `register` is the method every verb method calls: an address, the verbs as a
// list and the middleware as a list, the last of which answers. It hands back
// the layer it made, not the router, so it does not chain.

import type { Context, Middleware, Next } from 'koa';

export interface RouterOptions {
  prefix?: string;
}

export interface Layer {
  path: string;
  methods: string[];
}

declare class Router {
  constructor(options?: RouterOptions);
  get(path: string, ...handlers: Middleware[]): Router;
  post(path: string, ...handlers: Middleware[]): Router;
  register(path: string | string[], methods: string[], middleware: Middleware | Middleware[], opts?: object): Layer;
  use(...handlers: Middleware[]): Router;
  use(path: string, ...handlers: Middleware[]): Router;
  routes(): Middleware;
  allowedMethods(): Middleware;
}

export default Router;
export type { Context, Next };
